import pandas as pd

def clean(df):
    # Remove exact duplicate rows
    df = df.drop_duplicates().reset_index(drop=True)
    # Convert Price from text (e.g. "$6.00") to numeric
    df['Price'] = df['Price'].astype(str).str.replace('$', '', regex=False).astype(float)
    return df

def answer(df):
    return df.groupby('Category')['Price'].mean().to_dict()
